e.rep("  drawRule:{g:'retire', b:'B20', ty:3, n:'how you draw your pension',","  accessAge:{g:'retire', b:'B20', ty:3, n:'pension access age', l:'Earliest age you can draw your pension', t:'choice', o:[[60, 'From 60 (most pensions)'], [50, 'From 50 (some occupational schemes)']], sug:() => SV('accessAge'), get by(){ return STB.accessAge.by; }, need:() => false, get help(){ return SG('accessAge'); }},\n  drawRule:{g:'retire', b:'B20', ty:3, n:'how you draw your pension',")
