e.rep("const NB = {","const retMin = () => (S.about.age || 0) + 1, retMax = () => Math.max(retMin(), +asmV('planEnd') - 1);\nconst pRetMin = () => (finN('pAge') > 0 ? finN('pAge') : (S.about.age || 0)) + 1, pRetMax = () => Math.max(pRetMin(), pRetMin() - 1 + (+asmV('planEnd') - (S.about.age || 0)) - 1);\nconst NB = {")
