e.rep("  pret:{ lim(){ return {min:50, max:75, smax:75, widen:false, u:'age', int:true}; },","  pret:{ lim(){ return {min:pRetMin(), max:pRetMax(), smax:pRetMax(), widen:false, u:'age', int:true}; },")
e.rep("  retireAge:{l:'Retirement age', type:'num', min:50, max:75, pre:1, hint:'From your timeline flag'},","  retireAge:{l:'Retirement age', type:'num', pre:1, hint:'From your timeline flag'},")
